// === Tab: main ===
/*
______________________________________________________________________________

RGB Cube

Controls:
	* Use mouse to rotate around the cube
	* Use the scroll to zoom in and out
	* Hold keys 'o' or 'p' to increase and decrease the opacity of the balls

Author:
	Gaurav Dubal

Contact:
  gaurav_dubal@hotmail.co.uk

______________________________________________________________________________

*/

let ps;
var dist_from_cam = 500; 		// default camera distance
var cube_size = 10;					// number of balls per edge
var particles = [];

function setup() {
  createCanvas(1024, 768, WEBGL);

  ps = new ParticleSystem();
  ps.loadParticles();
}

function draw() {
  background(0);

  ps.run();
  lines();
  camera_view();
  keyPressed();
}

// creating red blue and green lines
function lines() {
  push();
  translate(-20 - 255 / 2, -20 - 255 / 2, -20 - 255 / 2);
  noStroke();
  fill(255);
  //sphere(5);
  pop();
  push();
  translate(-255 / 2, -255 / 2, -255 / 2);
  stroke(255, 0, 0);
  strokeWeight(5);
  //line(-20, -20, -20, 255 + 20, -20, -20);
  stroke(0, 255, 0);
  strokeWeight(5);
  //line(-20, -20, -20, -20, 255 + 20, -20);
  stroke(0, 0, 255);
  strokeWeight(5);
  //line(-20, -20, -20, -20, -20, 255 + 20);
  pop();
}

// changing location of camera based on mouse position
function camera_view() {
  // rotate around single point
  var rotation_angle = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, TWO_PI);
  var elevation_angle = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, PI);
	// for screenshotting
  // var rotation_angle = PI + PI / 4;
  // var elevation_angle = 2.0709
  var centerX = dist_from_cam * cos(rotation_angle) * sin(elevation_angle);
  var centerY = dist_from_cam * sin(rotation_angle) * sin(elevation_angle);
  var centerZ = dist_from_cam * cos(elevation_angle);
  camera(centerX, centerY, centerZ, 0, 0, 0, 0, 0, -1);
}

function mouseWheel(event) {
	// print(event.delta);
	dist_from_cam += event.delta;
}

function keyPressed() {
  var increment = 2;
  if (keyIsPressed) {
    // changing the opacity of particles
    if (key == "p") {
      for (let p of particles) {
        if (p.opacity < 255) {
          p.opacity += increment;
          // print("Opacity = " + p.opacity);
        }
      }
    }
    if (key == "o") {
      for (let p of particles) {
        if (p.opacity > 0) {
          p.opacity -= increment;
          // print("Opacity = " + p.opacity);
        }
      }
    }
  }
}

// === Tab: particle ===
class Particle {
  constructor(position_, col_, opacity_, diameter) {
    this.position = position_;
    this.col = col_;
    this.opacity = 255;
    this.diameter = (255 / (cube_size - 1)) / 2;
  }

  display() {
    push();
    translate(this.position.x, this.position.y, this.position.z);
    noStroke();
    fill(red(this.col), green(this.col), blue(this.col), this.opacity);
    sphere(this.diameter);
    pop();
  }
}

// === Tab: particle_system ===
class ParticleSystem {
  ParticleSystem() {

  }

  loadParticles() {
    var increment = int(255 / (cube_size - 1));
    for (var i = 0; i <= 255; i += increment) {
      for (var j = 0; j <= 255; j += increment) {
        for (var k = 0; k <= 255; k += increment) {
          let p = new Particle();
          p.position = new p5.Vector(i - 255 / 2, j - 255 / 2, k - 255 / 2);
          p.col = color(i, j, k, p.opacity);
          particles.push(p);
        }
      }
    }
  }

  run() {
    for (let p of particles) {
      p.display();
    }
  }
}

